package com.franco.desco.adapter.in.web.campaign;import io.swagger.v3.oas.annotations.media.Schema;import java.math.BigDecimal;import java.time.Instant;import java.time.LocalDate;import java.util.List;
public final class CampaignResponses{private CampaignResponses(){}@Schema(name="CampaignCreatedResponse")public record Created(Long campaniaVentaId){}@Schema(name="CampaignSummaryResponse")public record Summary(Long campaniaVentaId,String codigo,String nombre,LocalDate fechaInicio,LocalDate fechaFin,String estadoProceso,Long asociacionId,String asociacion,Long empresaCompradoraId,String comprador,String observacion,Long participantesActivos,Long operativos){}@Schema(name="CampaignParticipantResponse")public record Participant(Long participacionId,String estadoParticipacion,Long socioId,String numeroDocumento,String socioNombre){}@Schema(name="CampaignOperationResponse")public record Operation(Long operativoVentaId,String codigo,Instant fechaInicioProgramada,Instant fechaFinProgramada,Instant fechaInicioReal,Instant fechaFinReal,Integer cantidadJabasRecibidas,String estadoProceso,String observacion){}@Schema(name="CampaignPriceResponse")public record Price(Long precioComercialId,Long operativoVentaId,Integer variedadPaltaId,Long condicionComercialId,BigDecimal precio,String moneda,String unidadMedida,Instant fechaVigenciaDesde,Instant fechaVigenciaHasta,Integer version){}@Schema(name="CampaignDetailResponse")public record Detail(Summary campania,List<Participant>participantes,List<Operation>operativos,List<Price>precios){} }
